BEGIN;
CREATE TABLE IF NOT EXISTS oca.manifest_scan_runs(run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),scope_id UUID NOT NULL REFERENCES knowledge.scopes(scope_id),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,status TEXT NOT NULL CHECK(status IN ('running','succeeded','partial','failed')),branches_attempted INTEGER NOT NULL DEFAULT 0,branches_succeeded INTEGER NOT NULL DEFAULT 0,branches_failed INTEGER NOT NULL DEFAULT 0,manifests_processed INTEGER NOT NULL DEFAULT 0,manifests_failed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS oca.module_manifests(repository_id BIGINT NOT NULL REFERENCES oca.repositories(repository_id),branch_name TEXT NOT NULL,commit_sha TEXT NOT NULL,module_release_id UUID NOT NULL REFERENCES odoo.module_releases(module_release_id),artifact_id UUID NOT NULL REFERENCES source_registry.artifacts(artifact_id),relative_path TEXT NOT NULL,manifest_sha256 TEXT NOT NULL CHECK(manifest_sha256 ~ '^[0-9a-f]{64}$'),scan_run_id UUID NOT NULL REFERENCES oca.manifest_scan_runs(run_id),PRIMARY KEY(repository_id,branch_name,relative_path));
CREATE TABLE IF NOT EXISTS oca.manifest_scan_issues(issue_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES oca.manifest_scan_runs(run_id),repository_id BIGINT NOT NULL REFERENCES oca.repositories(repository_id),branch_name TEXT NOT NULL,relative_path TEXT,error_code TEXT NOT NULL,message TEXT NOT NULL);
INSERT INTO platform.schema_migrations(migration_id,checksum) VALUES('015_oca_manifest_inventory','managed-by-repository') ON CONFLICT DO NOTHING;
COMMIT;
